-- Local proposal only. 0004 is reserved; existing migrations are unchanged.
-- No public tables, bindings, jobs or grants are added.
CREATE TABLE research_sources ( source_id TEXT PRIMARY KEY, policy_version TEXT NOT NULL, config_hash TEXT NOT NULL, suspended INTEGER NOT NULL DEFAULT 0 CHECK(suspended IN (0,1)) );
CREATE TABLE research_runs ( run_id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES research_sources(source_id), config_hash TEXT NOT NULL, query_hash TEXT NOT NULL, policy_version TEXT NOT NULL, terms_version TEXT NOT NULL, scheduled_for TEXT NOT NULL, recorded_at TEXT NOT NULL, synthetic INTEGER NOT NULL CHECK(synthetic IN (0,1)), state TEXT NOT NULL CHECK(state IN ('collecting','partial','complete','purging','purged')), next_page INTEGER CHECK(next_page >= 0), observation_count INTEGER NOT NULL DEFAULT 0, http_page_attempts INTEGER NOT NULL DEFAULT 0 CHECK(http_page_attempts BETWEEN 0 AND 3), last_error TEXT, retry_at TEXT, lease_token TEXT, lease_until TEXT, evidence_expires_at TEXT NOT NULL, evidence_purged_at TEXT, normalized_expires_at TEXT NOT NULL );
CREATE INDEX research_runs_retention ON research_runs(normalized_expires_at,state);
CREATE INDEX research_runs_source ON research_runs(source_id,scheduled_for,state);
CREATE TABLE research_pages ( run_id TEXT NOT NULL REFERENCES research_runs(run_id), page_number INTEGER NOT NULL, evidence_key TEXT NOT NULL UNIQUE, evidence_hash TEXT NOT NULL, observed_at TEXT NOT NULL, evidence_expires_at TEXT NOT NULL, evidence_deleted_at TEXT, reported_total INTEGER, received_count INTEGER NOT NULL, coverage TEXT NOT NULL CHECK(coverage IN ('complete','partial')), PRIMARY KEY(run_id,page_number) );
CREATE TABLE research_observations ( observation_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES research_runs(run_id), page_number INTEGER NOT NULL, record_key TEXT NOT NULL, source_url TEXT NOT NULL, method_version TEXT NOT NULL, observed_at TEXT NOT NULL, recorded_at TEXT NOT NULL, record_hash TEXT NOT NULL, previous_observation_id TEXT, change_kind TEXT NOT NULL CHECK(change_kind IN ('first_seen','reobserved','revised')), domain_json TEXT NOT NULL CHECK(json_valid(domain_json)), UNIQUE(run_id,record_key) );
CREATE INDEX research_records_key ON research_observations(record_key,observed_at);
CREATE TRIGGER research_observations_immutable BEFORE UPDATE ON research_observations BEGIN SELECT RAISE(ABORT,'immutable_research_observation'); END;
CREATE TRIGGER research_observations_retention BEFORE DELETE ON research_observations WHEN (SELECT state FROM research_runs WHERE run_id=OLD.run_id) != 'purging' BEGIN SELECT RAISE(ABORT,'research_retention_required'); END;
CREATE UNIQUE INDEX research_one_run_per_day ON research_runs(source_id,substr(scheduled_for,1,10),synthetic);
